WITH "m0" AS ( UPDATE "public"."mutation_item" AS "s" SET "title" = $1 WHERE ( true AND ( ( true ) ) AND ( "s"."owner_id" = $2 ) ) RETURNING "s" AS "t0" , NULL::tid AS "k0" , CAST(CASE WHEN ( true ) THEN '1' ELSE 'rusuna: permission check failed' || left( "s"."ctid" ::text, 0) END AS integer) AS "check__constraint" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ) SELECT json_build_object( 'affected_rows' , (SELECT count(*) FROM "r0" ) )
